class ai_goal;

extern "C" void *memmove(void *, const void *, unsigned int);
extern "C" void *arch_malloc(unsigned int, const char *, int);
extern "C" void arch_free(void *);

template<int __inst>
class __malloc_alloc_template {
public:
    static void *_S_oom_malloc(unsigned int);
    static void *allocate(unsigned int __n) {
        void *__result = arch_malloc(__n, __FILE__, 0);
        if (__result == 0) __result = _S_oom_malloc(__n);
        return __result;
    }
    static void deallocate(void *__p, unsigned int) { arch_free(__p); }
};

template<class _T1, class _T2>
inline void construct(_T1 *__p, const _T2 &__value) {
    if (__p) *__p = __value;
}

template<class _Tp>
inline _Tp *copy(const _Tp *__first, const _Tp *__last, _Tp *__result) {
    memmove(__result, __first, sizeof(_Tp) * (__last - __first));
    return __result + (__last - __first);
}

template<class _Tp>
inline _Tp *copy_backward(const _Tp *__first, const _Tp *__last,
                          _Tp *__result) {
    unsigned int __count = __last - __first;
    memmove(__result - __count, __first, sizeof(_Tp) * __count);
    return __result - __count;
}

template<class _Tp>
inline _Tp *uninitialized_copy(const _Tp *__first, const _Tp *__last,
                               _Tp *__result) {
    return copy(__first, __last, __result);
}

template<class _Tp>
inline void destroy(_Tp *, _Tp *) {}

template<class _Tp, class _Alloc>
class _Vector_base {
public:
    typedef unsigned int size_type;
    typedef _Tp *iterator;
    _Tp *_M_start;
    _Tp *_M_finish;
    _Tp *_M_end_of_storage;
    iterator _M_allocate(size_type __n) {
        return __n ? (iterator)_Alloc::allocate(__n * sizeof(_Tp)) : 0;
    }
    void _M_deallocate(iterator __p, size_type __n) {
        if (__p) _Alloc::deallocate(__p, __n * sizeof(_Tp));
    }
};

template<class _Tp, class _Alloc>
class vector : protected _Vector_base<_Tp, _Alloc> {
public:
    typedef _Tp value_type;
    typedef value_type *iterator;
    typedef unsigned int size_type;
    iterator begin() { return _M_start; }
    iterator end() { return _M_finish; }
    size_type size() const { return size_type(_M_finish - _M_start); }
    void _M_insert_aux(iterator __position, const _Tp &__x);
};

template<class _Tp, class _Alloc>
void vector<_Tp, _Alloc>::_M_insert_aux(iterator __position,
                                        const _Tp &__x) {
    if (_M_finish != _M_end_of_storage) {
        construct(_M_finish, *(_M_finish - 1));
        ++_M_finish;
        _Tp __x_copy = __x;
        copy_backward(__position, _M_finish - 2, _M_finish - 1);
        *__position = __x_copy;
    }
    else {
        const size_type __old_size = size();
        const size_type __len = __old_size != 0 ? 2 * __old_size : 1;
        iterator __new_start = _M_allocate(__len);
        iterator __new_finish = __new_start;
        __new_finish = uninitialized_copy(_M_start, __position, __new_start);
        construct(__new_finish, __x);
        ++__new_finish;
        __new_finish = uninitialized_copy(__position, _M_finish,
                                          __new_finish);
        destroy(begin(), end());
        _M_deallocate(_M_start, _M_end_of_storage - _M_start);
        _M_start = __new_start;
        _M_finish = __new_finish;
        _M_end_of_storage = __new_start + __len;
    }
}

template void vector<ai_goal *, __malloc_alloc_template<0> >::_M_insert_aux(
    ai_goal **, ai_goal *const &);
